def collect_relevant_files(root: Path) -> list:
    """Walks the extracted project and returns paths worth analyzing."""
    relevant = []
    for path in root.rglob("*"):
        if not path.is_file():
            continue
        if is_ignored(path, root):
            continue
        relevant.append(path)
    return relevant

